                public final int nights = d.getNights();
                public final Object subtotal = d.getSubtotal();
                public final Object discount = d.getDiscount();
                public final Object total = d.getTotal();
            };
        }
        return doc;
    }

    private static Object buildDocument(Reservation res) throws SQLException {
        var room = roomRepository.findByNumber(res.getRoomNumber());
        String roomType = room != null ? room.getType().name() : "UNKNOWN";

        return new ReservationDocument(
            res.getId(),
            res.getGuestName(),
            res.getGuestCpf(),
            res.getRoomNumber(),
            roomType,
            res.getCheckIn(),
            res.getCheckOut(),
            res.getNights(),
            res.getSubtotal(),
            res.getDiscount(),
            res.getTotal()
        );
    }

    private static Object error(String code, String message) {
        return new Object() {
            public final String error = code;
            public final String message = message;
        };
    }

    public static class CreateReservationRequest {
